// Guards the generated-output cleaner.
//
// The cleaner runs before every emission, so a defect here either destroys the
// hand-written `@method` implementations kept in extension seams or silently
// leaves stale generated files behind. Both failure modes are quiet, which is
// why they are asserted rather than left to review.

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { cleanJavaOutput, MARKER, SEAM_MARKER, SEAM_MARKERS } from "./clean-java-output.mjs";

function withRoot(files, run) {
  const dir = mkdtempSync(join(tmpdir(), "clean-java-"));
  const root = join(dir, "model");
  mkdirSync(root);
  for (const [name, text] of Object.entries(files)) {
    writeFileSync(join(root, name), text, "utf8");
  }
  try {
    return run(root);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const generated = `${MARKER}\n// Code generated by Typra emitter; DO NOT EDIT.\npackage p;\n`;
const seam = `${SEAM_MARKER}\npackage p;\nclass MessageMethods { static String text() { return "hand written"; } }\n`;

test("removes generated files", () => {
  withRoot({ "Message.java": generated }, (root) => {
    const result = cleanJavaOutput([root]);
    assert.equal(result.removed.length, 1);
    assert.ok(!existsSync(join(root, "Message.java")));
  });
});

test("preserves extension seams and their hand-written bodies", () => {
  withRoot({ "Message.java": generated, "MessageMethods.java": seam }, (root) => {
    const result = cleanJavaOutput([root]);
    assert.deepEqual(result.preserved, [join(root, "MessageMethods.java")]);
    assert.ok(existsSync(join(root, "MessageMethods.java")));
    assert.ok(!existsSync(join(root, "Message.java")));
  });
});

test("preserves a seam whose name defeats a file-name pattern", () => {
  // Typra's PascalCase conversion leaves the underscore before a digit
  // (`foo_1` -> `Foo_1`), so seams are matched on their marker, not their name.
  withRoot({ "Foo_1Methods.java": seam }, (root) => {
    const result = cleanJavaOutput([root]);
    assert.equal(result.preserved.length, 1);
    assert.ok(existsSync(join(root, "Foo_1Methods.java")));
  });
});

test("preserves a seam opened by any accepted marker", () => {
  // The pinned emitter opens a seam with prose; later lines front the file with
  // a stable machine-readable tag. The cleaner is fail-closed, so an unrecognised
  // spelling would abort the build instead of preserving hand-written code.
  SEAM_MARKERS.forEach(({ marker }, index) => {
    withRoot({ [`Message${index}Methods.java`]: `${marker}\npackage p;\n` }, (root) => {
      const result = cleanJavaOutput([root]);
      assert.equal(result.preserved.length, 1, `marker not accepted: ${marker}`);
      assert.equal(result.removed.length, 0);
    });
  });
});

test("a tag marker must be the whole opening line", () => {
  // Prefix matching would let a marker be smuggled in ahead of unrelated
  // content, so tag markers are compared against the complete opening line.
  // The pinned prose marker is the documented exception: its real form carries
  // a trailing sentence, so it stays a prefix match.
  for (const { marker, exact } of SEAM_MARKERS) {
    const smuggled = { "Stray.java": `${marker}-not-a-seam\npackage p;\n` };
    if (exact) {
      withRoot(smuggled, (root) => {
        assert.throws(() => cleanJavaOutput([root]), /missing the generated marker/u, marker);
      });
    } else {
      withRoot(smuggled, (root) => {
        assert.equal(cleanJavaOutput([root]).preserved.length, 1, marker);
      });
    }
  }
});

test("no seam marker can shadow the generated marker", () => {
  // A seam marker that prefixed the generated marker would strand every
  // generated file, so the two sets must stay disjoint.
  for (const { marker } of SEAM_MARKERS) {
    assert.ok(!MARKER.startsWith(marker), `seam marker shadows generated files: ${marker}`);
    assert.ok(!marker.startsWith(MARKER), `generated marker shadows a seam: ${marker}`);
  }
});

test("refuses to clean an unmarked hand-written file", () => {
  withRoot({ "Stray.java": "package p;\nclass Stray { }\n" }, (root) => {
    assert.throws(() => cleanJavaOutput([root]), /missing the generated marker/u);
    assert.ok(existsSync(join(root, "Stray.java")));
  });
});

test("requires the marker at the start of the file", () => {
  withRoot({ "Late.java": `package p;\n${MARKER}\n` }, (root) => {
    assert.throws(() => cleanJavaOutput([root]), /missing the generated marker/u);
  });
});

test("rejects non-Java files in the generated directory", () => {
  withRoot({ "notes.txt": "scratch" }, (root) => {
    assert.throws(() => cleanJavaOutput([root]), /Unexpected non-Java file/u);
  });
});

test("is idempotent across repeated runs", () => {
  // Regression guard: the cleaner previously threw on the second regeneration
  // because the seam it had preserved was then treated as a stray file.
  withRoot({ "Message.java": generated, "MessageMethods.java": seam }, (root) => {
    cleanJavaOutput([root]);
    const second = cleanJavaOutput([root]);
    assert.deepEqual(second.removed, []);
    assert.equal(second.preserved.length, 1);
  });
});

test("skips roots that do not exist", () => {
  const result = cleanJavaOutput([join(tmpdir(), "clean-java-does-not-exist")]);
  assert.deepEqual(result, { removed: [], preserved: [] });
});
